      "第三者（ブローカーや情報ベンダー）から入手した価格であれば、その算定に用いられたインプットの内容に関わらず、すべて「レベル1」の時価に分類される。",
      "期末日における市場が極端に混乱し取引量が著しく減少している場合であっても、直近の取引価格を無条件にそのまま時価としなければならず、調整を行うことは一切禁じられている。"
