    question: "会社法における剰余金の配当に伴う準備金の積立てに関する以下のデータに基づき、当期の配当時に積み立てなければならない「利益準備金」の金額として、最も適切なものはどれか。\n【純資産データ】\n・資本金：10,000 千円\n・資本準備金：1,500 千円\n・利益準備金：600 千円\n・その他利益剰余金（繰越利益剰余金）を原資とする当期の配当支払額：5,000 千円",
