    question: "ある工場では共通の機械設備を使用して製品Aと製品Bを製造している。機械設備の月間最大稼働可能時間は 1,200時間であり、これが唯一の制約条件である。以下のデータに基づき、月間の営業利益を最大化する最適プロダクト・ミックス（生産・販売量の組み合わせ）を選択した場合、獲得できる月間最大限界利益はいくらか。\n【製品データ】\n・製品A：単位当たり限界利益 3,000円、1個当たり機械稼働時間 3時間、月間最大需要量 300個\n・製品B：単位当たり限界利益 2,400円、1個当たり機械稼働時間 2時間、月間最大需要量 400個",
