      "○ 正しい！キャッシュ・フローの符号（マイナス・プラス）が期間中に2回以上反転する場合（例：－ → ＋ → －）、代数方程式の解の性質上、複数のIRRが存在したり解が存在しなかったりする欠点があります。",
      "× IRR法は「比率（利回り）」のみを見るため投資規模を無視してしまいます。資本コスト8%のもとでは、小規模で高利回りな案Aより、大規模で資本コストを上回る案Bの方が獲得できる正味現在価値（NPVの絶対額）がはるかに大きくなるケースが多々あります。",
