    question: "等級別総合原価計算を採用している工場において、当月に同一工程からサイズのみが異なる等級製品X（大型）と等級製品Y（小型）が完成した。以下のデータに基づき、等価係数を用いて完成品原価を按分した場合、等級製品Xの「1個当たり完成品単位原価」はいくらか。\n【当月完成データ】\n・当月結合完成品原価総額：1,300,000 円\n・等級製品X：完成品数量 200個、等価係数 1.5\n・等級製品Y：完成品数量 350個、等価係数 1.0",
