    question: "ある工場の過去半年間の月間生産量と製造原価総額の実績データは以下のとおりである。「高低点法」を用いて製造原価を変動費と固定費に分解した場合、「製品1個当たり変動費」および「月間固定費」の組み合わせとして、最も適切なものはどれか。\n【月次実績データ】\n・4月：生産量 1,200個、製造原価 1,100千円（最高操業度月）\n・5月：生産量 900個、製造原価 950千円\n・6月：生産量 700個、製造原価 800千円（最低操業度月）\n・7月：生産量 1,000個、製造原価 1,020千円\n・8月：生産量 800個、製造原価 880千円\n・9月：生産量 1,100個、製造原価 1,060千円",
